package tn.esprit.jungleinenglishbackend.Models.dto;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * DTO representing aggregated sales data for a single product.
 * Used in top-selling product rankings and inventory analysis.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class ProductSalesDTO {

    private Integer productId;
    private String productTitle;

    /** Total number of units sold across all orders. */
    private Long totalQuantitySold;

    /**
     * Total revenue generated by this product (price × quantity across all orders).
     */
    private Double totalRevenue;
}
